/* M1 tokenizer + protocol parity against the lyra reference stack
 * (fixtures generated by gen_tokenizer_fixture.py). */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "yue.h"
#include "yue_json.h"
#include "yue_protocol.h"

static int failures;

static void check(int condition, const char *name) {
    printf("%-46s %s\n", name, condition ? "ok" : "FAIL");
    if (!condition) failures++;
}

static yw_json *load_fixture(const char *name) {
    char path[512];
    snprintf(path, sizeof(path), "tests/tokenizer_fixture/%s", name);
    FILE *handle = fopen(path, "rb");
    if (!handle) return NULL;
    fseek(handle, 0, SEEK_END);
    long size = ftell(handle);
    fseek(handle, 0, SEEK_SET);
    char *text = malloc((size_t)size + 1);
    size_t got = fread(text, 1, (size_t)size, handle);
    fclose(handle);
    text[got] = '\0';
    yw_json *value = NULL;
    char error[YUE_ERROR_SIZE];
    if (yw_json_parse(text, &value, error, sizeof(error)) == 0) {
        fprintf(stderr, "fixture %s parse failed: %s\n", name, error);
        free(text);
        return NULL;
    }
    free(text);
    return value;
}

static void free_ids(uint32_t *ids) { free(ids); }

int main(void) {
    char error[YUE_ERROR_SIZE];
    h3_tokenizer *tok = h3_tokenizer_load_tiktoken(
        "/Volumes/Work/models/YuE2.models/lyra-YuE2-3B/qwen.tiktoken",
        error, sizeof(error));
    if (!tok) {
        fprintf(stderr, "tokenizer load failed: %s\n", error);
        return 1;
    }
    check(1, "tiktoken load (151643 ranks)");

    /* ---- encode parity ---- */
    yw_json *cases = load_fixture("encode.json");
    int encode_ok = cases != NULL;
    size_t total = cases ? yw_json_count(cases) : 0;
    for (size_t i = 0; encode_ok && i < total; i++) {
        const yw_json *entry = yw_json_at(cases, i);
        const char *text = yw_json_get_string(entry, "text", "");
        const yw_json *expected = yw_json_get(entry, "ids");
        uint32_t *ids = NULL;
        size_t count = 0;
        if (!h3_tokenizer_encode(tok, text, 0, &ids, &count, error,
                                 sizeof(error))) {
            fprintf(stderr, "encode failure on case %zu: %s\n", i, error);
            encode_ok = 0;
            break;
        }
        int same = count == yw_json_count(expected);
        for (size_t k = 0; same && k < count; k++)
            same = ids[k] == (uint32_t)yw_json_number(yw_json_at(expected, k));
        if (!same) {
            fprintf(stderr,
                    "encode mismatch case %zu text='%.40s' count=%zu\n", i,
                    text, count);
            encode_ok = 0;
        }
        free_ids(ids);
    }
    if (cases) yw_json_free(cases);
    check(encode_ok, "encode parity (20 cases incl. CJK/emoji/specials)");

    /* ---- decode parity (specials rendered, codec ids skipped) ---- */
    cases = load_fixture("decode.json");
    int decode_ok = cases != NULL;
    total = cases ? yw_json_count(cases) : 0;
    for (size_t i = 0; decode_ok && i < total; i++) {
        const yw_json *entry = yw_json_at(cases, i);
        const yw_json *ids_json = yw_json_get(entry, "ids");
        size_t count = yw_json_count(ids_json);
        uint32_t *ids = malloc(count * sizeof(*ids));
        for (size_t k = 0; k < count; k++)
            ids[k] = (uint32_t)yw_json_number(yw_json_at(ids_json, k));
        char *text = h3_tokenizer_decode(tok, ids, count, error, sizeof(error));
        free(ids);
        const char *want = yw_json_get_string(entry, "text", "");
        if (!text || strcmp(text, want) != 0) {
            fprintf(stderr, "decode mismatch case %zu: got '%s' want '%s'\n",
                    i, text ? text : "(null)", want);
            decode_ok = 0;
        }
        free(text);
    }
    if (cases) yw_json_free(cases);
    check(decode_ok, "decode parity (specials + codec skip)");

    /* ---- prefix construction parity ---- */
    cases = load_fixture("prefix.json");
    int prefix_ok = cases != NULL;
    total = cases ? yw_json_count(cases) : 0;
    const char *style =
        "upbeat synth-pop, female vocals, 128 BPM";
    const char *lyrics =
        "[Verse]\nCity lights are burning slow\n[Chorus]\nWe run, we run";
    const char *abc_text =
        "X:1\nT:Fixture\nM:4/4\nL:1/8\nK:C\n|:C2DE G2AB|c2BA GED2:|";
    for (size_t i = 0; prefix_ok && i < total; i++) {
        const yw_json *entry = yw_json_at(cases, i);
        const char *cot = yw_json_get_string(entry, "cot", "");
        /* fixture label "full+plan" exercises the planning prefix, which
         * still uses the full-mode template (only abc_ids differ). */
        int cot_index = strcmp(cot, "full+plan") == 0 ? YUE_COT_FULL
                                                      : yue_cot_index(cot);
        uint32_t *abc_ids = NULL;
        size_t abc_count = 0;
        if (strcmp(cot, "off") != 0 && strcmp(cot, "full+plan") != 0) {
            if (!h3_tokenizer_encode(tok, abc_text, 0, &abc_ids, &abc_count,
                                     error, sizeof(error))) {
                prefix_ok = 0;
                break;
            }
        }
        const yw_json *want_prefix = yw_json_get(entry, "prefix");
        const yw_json *want_negative = yw_json_get(entry, "negative");

        uint32_t *prefix = NULL;
        size_t prefix_count = 0;
        if (!yue_token_prefixes(tok, style, lyrics, cot_index, abc_ids,
                                abc_count, &prefix, &prefix_count, error,
                                sizeof(error))) {
            fprintf(stderr, "prefix build failed (%s): %s\n", cot, error);
            prefix_ok = 0;
            free_ids(abc_ids);
            break;
        }
        int same = prefix_count == yw_json_count(want_prefix);
        for (size_t k = 0; same && k < prefix_count; k++)
            same = prefix[k] ==
                   (uint32_t)yw_json_number(yw_json_at(want_prefix, k));
        if (!same)
            fprintf(stderr, "prefix mismatch (%s): got %zu rows\n", cot,
                    prefix_count);
        prefix_ok = prefix_ok && same;
        free_ids(prefix);

        if (want_negative && yw_json_type(want_negative) == yue_json_ARRAY) {
            uint32_t *neg = NULL;
            size_t neg_count = 0;
            if (!yue_negative_prefix(tok, style, lyrics, cot_index, abc_ids,
                                     abc_count, &neg, &neg_count, error,
                                     sizeof(error))) {
                fprintf(stderr, "negative build failed (%s): %s\n", cot,
                        error);
                prefix_ok = 0;
            } else {
                same = neg_count == yw_json_count(want_negative);
                for (size_t k = 0; same && k < neg_count; k++)
                    same = neg[k] == (uint32_t)yw_json_number(
                                        yw_json_at(want_negative, k));
                if (!same)
                    fprintf(stderr, "negative mismatch (%s)\n", cot);
                prefix_ok = prefix_ok && same;
                free_ids(neg);
            }
        }
        free_ids(abc_ids);
    }
    if (cases) yw_json_free(cases);
    check(prefix_ok, "prefix/negative parity (all cot modes)");

    /* negative without ABC must be rejected for symbolic modes */
    uint32_t *neg = NULL;
    size_t neg_count = 0;
    check(!yue_negative_prefix(tok, style, lyrics, YUE_COT_FULL, NULL, 0,
                               &neg, &neg_count, error, sizeof(error)) &&
              neg == NULL,
          "negative without ABC rejected (symbolic CFG)");

    /* ---- chunk_ranges parity ---- */
    cases = load_fixture("chunk.json");
    int chunk_ok = cases != NULL;
    total = cases ? yw_json_count(cases) : 0;
    for (size_t i = 0; chunk_ok && i < total; i++) {
        const yw_json *entry = yw_json_at(cases, i);
        size_t frames = (size_t)yw_json_get_number(entry, "frames", 0);
        size_t prefix = (size_t)yw_json_get_number(entry, "prefix", 0);
        const yw_json *want = yw_json_get(entry, "ranges");
        const yw_json *want_error = yw_json_get(entry, "error");
        yue_chunk_range ranges[16];
        size_t count = 0;
        int ok = yue_chunk_ranges(frames, prefix, YUE_CONTEXT, ranges, 16,
                                  &count, error, sizeof(error));
        if (want_error) {
            ok = !ok;
        } else if (ok) {
            ok = count == yw_json_count(want);
            for (size_t k = 0; ok && k < count; k++) {
                const yw_json *pair = yw_json_at(want, k);
                ok = ranges[k].start == (size_t)yw_json_number(yw_json_at(pair, 0)) &&
                     ranges[k].end == (size_t)yw_json_number(yw_json_at(pair, 1));
            }
        } else {
            ok = 0;
        }
        if (!ok) fprintf(stderr, "chunk mismatch case %zu\n", i);
        chunk_ok = chunk_ok && ok;
    }
    if (cases) yw_json_free(cases);
    check(chunk_ok, "chunk_ranges parity");

    /* ---- generation config defaults ---- */
    cases = load_fixture("generation_config.json");
    int config_ok = cases != NULL;
    yue_generation_config cfg;
    if (config_ok &&
        !yue_generation_config_load("/nonexistent-dir", &cfg, error,
                                    sizeof(error))) {
        config_ok = 0;
    }
    if (config_ok) {
        const yw_json *abc = yw_json_get(cases, "abc");
        const yw_json *semantic = yw_json_get(cases, "semantic");
        config_ok =
            cfg.abc.temperature == yw_json_get_number(abc, "temperature", -1) &&
            cfg.abc.top_k == (int)yw_json_get_number(abc, "top_k", -1) &&
            cfg.abc.max_tokens == (int)yw_json_get_number(abc, "max_tokens", -1) &&
            cfg.semantic.temperature == yw_json_get_number(semantic, "temperature", -1) &&
            cfg.semantic.max_tokens == (int)yw_json_get_number(semantic, "max_tokens", -1) &&
            cfg.ode_steps == (int)yw_json_get_number(cases, "ode_steps", -1);
    }
    if (cases) yw_json_free(cases);
    check(config_ok, "generation config defaults parity");

    /* guidance defaults */
    check(yue_request_guidance(YUE_COT_OFF, 0, 0) == 1.01 &&
              yue_request_guidance(YUE_COT_FULL, 0, 0) == 1.0 &&
              yue_request_guidance(YUE_COT_FULL, 1.2, 1) == 1.2,
          "guidance defaults (off=1.01, else 1.0, explicit wins)");

    h3_tokenizer_free(tok);
    printf("m1 tokenizer tests: %d failure(s)\n", failures);
    return failures ? 1 : 0;
}
